using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;using System.Windows.Threading;
class SelectionCheck {
 static TV tv;static int count;static object Field(string n){return typeof(TV).GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(tv);}static void Set(string n,object v){typeof(TV).GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).SetValue(tv,v);}static object Call(string n,params object[] args){return typeof(TV).GetMethod(n,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(tv,args);}static void Check(bool ok,string label){if(!ok)throw new Exception(label);Console.WriteLine("PASS "+label);count++;}
 static IEnumerable<T> Walk<T>(DependencyObject root)where T:DependencyObject{if(root is T)yield return (T)root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var child in Walk<T>(VisualTreeHelper.GetChild(root,i)))yield return child;}
 static void ClickCell(DataGridCell cell){cell.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice,Environment.TickCount,MouseButton.Left){RoutedEvent=Mouse.PreviewMouseDownEvent});tv.UpdateLayout();}
 [STAThread]static int Main(){try{new Application();System.Threading.SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());tv=new TV();Set("serial","192.0.2.1:5555");Set("scannedFor","192.0.2.1:5555");Check(!(bool)Call("IsProtected","com.android.systemui"),"no core uninstall policy");var a=new Package{Id="com.demo.alpha",Name="Alpha",Path="/data/app/a.apk",State="已安装",Group="普通精简"};var b=new Package{Id="com.demo.beta",Name="Beta",Path="/data/app/b.apk",State="已停用",Group="普通精简"};var hidden=new Package{Id="com.demo.hidden",Name="Hidden",Path="/data/app/h.apk",State="已安装",Group="深度精简",Pick=true};var core=new Package{Id="com.vendor.launcher",Name="Core",Path="/system/a.apk",State="已安装",Group="桌面精简",Risk="疑似系统组件",IsLauncher=true,System=true};Set("packages",new List<Package>{a,b,hidden,core});Call("Show","步骤3");tv.Show();tv.UpdateLayout();var grid=(DataGrid)Field("grid");var toggle=Walk<Button>(tv).FirstOrDefault(x=>Convert.ToString(x.Content)=="全部选定");Check(toggle!=null,"bulk button initially says 全部选定");var source=grid.ItemsSource;toggle.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));tv.UpdateLayout();Check(a.Pick&&b.Pick&&hidden.Pick&&core.Pick,"bulk selection includes installed core rows");Check(Convert.ToString(toggle.Content)=="取消选定","all eligible visible rows change label to 取消选定");Check(ReferenceEquals(source,grid.ItemsSource),"bulk selection preserves grid ItemsSource");toggle.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(!a.Pick&&!b.Pick&&!hidden.Pick,"second bulk click clears visible selection");var row=(DataGridRow)grid.ItemContainerGenerator.ContainerFromItem(a);var cell=Walk<DataGridCell>(row).First(x=>x.Column.DisplayIndex==0);var box=Walk<CheckBox>(cell).First();double width=cell.ActualWidth;var position=box.TranslatePoint(new Point(0,0),grid);ClickCell(cell);Check(a.Pick&&box.IsChecked==true,"first checkbox-cell click immediately selects model and checkbox");Check(ReferenceEquals(box,Walk<CheckBox>(cell).First()),"checkbox click preserves checkbox visual");ClickCell(cell);Check(!a.Pick&&box.IsChecked==false,"second checkbox-cell click clears immediately");var nameCell=Walk<DataGridCell>(row).First(x=>x.Column.DisplayIndex==1);ClickCell(nameCell);nameCell.Focus();tv.UpdateLayout();Check(!a.Pick,"app name click does not change checkbox state");Check(cell.ActualWidth==width&&box.TranslatePoint(new Point(0,0),grid)==position,"name cell focus does not shift checkbox");var coreRow=(DataGridRow)grid.ItemContainerGenerator.ContainerFromItem(core);ClickCell(Walk<DataGridCell>(coreRow).First(x=>x.Column.DisplayIndex==0));Check(core.Pick,"direct checkbox click selects core row");hidden.Pick=true;((ComboBox)Field("groupFilter")).SelectedItem="普通精简";tv.UpdateLayout();source=grid.ItemsSource;toggle.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(a.Pick&&b.Pick&&hidden.Pick,"filtered bulk select preserves hidden selection");toggle.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(!a.Pick&&!b.Pick&&hidden.Pick,"filtered bulk clear preserves hidden selection");Check(ReferenceEquals(source,grid.ItemsSource),"filtered toggle preserves grid rows");((TextBox)Field("search")).Text="no matching rows";Check(Convert.ToString(toggle.Content)=="全部选定"&&!toggle.IsEnabled,"empty view has disabled 全部选定 button");Call("Show","步骤4");Set("newLauncher",core.Id);Call("Bind");Check(((DataGrid)Field("grid")).Items.Cast<Package>().Contains(core),"current replacement launcher is not hidden by policy");Check((bool)Call("Selectable",b),"disabled installed package remains selectable");Call("Show","步骤3");Check(((ComboBox)Field("groupFilter")).Items.Count==6,"filter contains all plus two local and three AI classes");Check(!Walk<Button>(tv).Any(x=>Convert.ToString(x.Content).Contains("解锁")),"no dedicated unlock flow");tv.Close();Console.WriteLine(count+" selection checks passed");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
